from __future__ import annotations

import json
from pathlib import Path


ROOT = Path(__file__).resolve().parents[1]
SCENARIOS = ROOT / "scenarios"
SCHEMA_VERSION = "mvi-scenario-v1"


def build_scenario(family: str, scenario_id: str, task: str, token_budget: int, valid1: str, valid2: str, invalid: str, split: str = "public") -> dict:
    prefix = scenario_id
    return {
        "schema_version": SCHEMA_VERSION,
        "scenario_id": scenario_id,
        "family": family,
        "split": split,
        "task": task,
        "repo_state_fingerprint": f"{scenario_id}-repo-v1",
        "token_budget": token_budget,
        "candidate_memories": [
            {
                "id": f"{prefix}-s1",
                "tier": "session",
                "content": valid1,
                "validity": "valid",
                "bucket": "critical",
            },
            {
                "id": f"{prefix}-p1",
                "tier": "project",
                "content": valid2,
                "validity": "valid",
                "bucket": "supporting",
            },
            {
                "id": f"{prefix}-x1",
                "tier": "session",
                "content": invalid,
                "validity": "stale",
                "bucket": "supporting",
            },
        ],
        "gold_valid_ids": [f"{prefix}-s1", f"{prefix}-p1"],
        "gold_invalid_ids": [f"{prefix}-x1"],
        "preferred_order_buckets": [
            {"name": "critical", "memory_ids": [f"{prefix}-s1"]},
            {"name": "supporting", "memory_ids": [f"{prefix}-p1"]},
        ],
        "task_outcome_baselines": {"no_memory": 0.15, "ideal": 1.0},
    }


def write(path: Path, data: dict) -> None:
    path.parent.mkdir(parents=True, exist_ok=True)
    path.write_text(json.dumps(data, indent=2) + "\n", encoding="utf-8")


def normalize_existing() -> None:
    for path in SCENARIOS.rglob("*.json"):
        data = json.loads(path.read_text(encoding="utf-8"))
        changed = False
        if data.get("schema_version") != SCHEMA_VERSION:
            data["schema_version"] = SCHEMA_VERSION
            changed = True
        if "split" not in data:
            data["split"] = "public"
            changed = True
        if changed:
            write(path, data)


